// Produces the form of this package that the edge runtime hands to a user
// worker.
//
// A deployed function imports `@mako-cloud/edge-sdk`. The worker has no npm,
// no network, and may read nothing outside its own directory, so the runtime
// materializes this module into the worker and maps the specifier onto it.
//
// The runtime serves its main worker from an in-memory eszip under a synthetic
// `/var/tmp/sb-compile-edge-runtime` root -- no file next to `supervisor.ts`
// exists on disk to read -- so the SDK travels as a module of that graph: this
// script emits its source as a string constant the supervisor imports.
//
// That only works while the emitted JavaScript is self-contained. `client.ts`
// imports types only, so `tsc` emits a module with no imports at all, and this
// script checks that before writing.
//
//   node scripts/build-runtime-module.mjs           # write
//   node scripts/build-runtime-module.mjs --check   # fail when out of date
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const packageRoot = dirname(dirname(fileURLToPath(import.meta.url)));
export const EMITTED_MODULE = join(packageRoot, "dist", "client.js");
export const RUNTIME_MODULE = join(
  packageRoot,
  "..",
  "cli",
  "runtime",
  "main",
  "edge-sdk-source.ts",
);

const BANNER = `// Generated by packages/edge-sdk/scripts/build-runtime-module.mjs -- do not edit.
//
// The edge SDK as the pinned runtime supplies it to a user worker: the emitted
// JavaScript of packages/edge-sdk/src/client.ts, which imports nothing. The
// supervisor writes this source into the worker directory and maps the bare
// specifier "@mako-cloud/edge-sdk" onto it.
//
// It is a string rather than a module because the runtime serves the main
// worker from an eszip: only the module graph reaches the container, and the
// supervisor needs the source text, not the exports.
`;

/** The exact bytes the runtime module must hold for the current SDK source. */
export function renderRuntimeModule() {
  const emitted = readFileSync(EMITTED_MODULE, "utf8");
  if (/^\s*(?:import|export)\s[^;]*\sfrom\s/mu.test(emitted)) {
    throw new Error(
      "packages/edge-sdk/dist/client.js has a module import; the runtime module must be self-contained",
    );
  }
  // The source map next to `dist/client.js` never reaches the worker, so the
  // comment pointing at it would only be a dangling reference.
  const source = emitted.replace(/\n?\/\/# sourceMappingURL=\S*\n?$/u, "\n");
  const quoted = source
    .replaceAll("\\", "\\\\")
    .replaceAll("`", "\\`")
    .replaceAll("${", "\\${");
  return `${BANNER}\nexport const EDGE_SDK_SOURCE = \`${quoted}\`;\n`;
}

function main() {
  const expected = renderRuntimeModule();
  if (process.argv.includes("--check")) {
    const actual = readFileSync(RUNTIME_MODULE, "utf8");
    if (actual !== expected) {
      process.stderr.write(
        `${RUNTIME_MODULE} is out of date; run \`npm run build:runtime-module -w @mako-cloud/edge-sdk\`\n`,
      );
      process.exitCode = 1;
    }
    return;
  }
  writeFileSync(RUNTIME_MODULE, expected);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
